from typing import List

class Solution:
    def jump(self, nums: List[int]) -> int:
        n = len(nums)

        def dfs(i: int) -> int:
            if i >= n - 1:
                return 0
            best = float("inf")
            for step in range(1, nums[i] + 1):
                best = min(best, 1 + dfs(i + step))
            return best

        return dfs(0)

